import './design/fonts.css';
import './design/tokens.css';
import type { App, GpuInfo } from './app/app';
import { attachDisplay, runConsole } from './app/presenter';

declare global {
  interface Window {
    __status?: unknown;
    __capture?: () => Promise<void>;
    __app?: App;
  }
}

/** What this browser can actually render with (WebGPU adapter, WebGL2 context). */
type AdapterInfo = { vendor?: string; architecture?: string; description?: string; isFallbackAdapter?: boolean };
async function capability(forceWebGL: boolean): Promise<{ webgpu: string; webgl2: string; ok: boolean; gpu: GpuInfo | null }> {
  let webgpu = '浏览器不支持';
  let info: GpuInfo | null = null;
  const gpu = (navigator as Navigator & { gpu?: { requestAdapter: (o?: object) => Promise<{ info?: AdapterInfo } | null> } }).gpu;
  if (forceWebGL) webgpu = '未使用（?webgl）';
  else if (gpu) {
    try {
      const a = await gpu.requestAdapter({ powerPreference: 'high-performance' });
      webgpu = a ? (a.info?.isFallbackAdapter ? '可用（软件适配器）' : '可用') : '没有可用的显卡适配器';
      if (a?.info) info = { vendor: a.info.vendor ?? '', architecture: a.info.architecture ?? '', description: a.info.description ?? '', fallback: !!a.info.isFallbackAdapter };
    } catch (e) {
      webgpu = `出错（${String(e).slice(0, 80)}）`;
    }
  }
  let webgl2 = '不可用';
  try {
    const gl = document.createElement('canvas').getContext('webgl2');
    if (gl) {
      webgl2 = '可用';
      gl.getExtension('WEBGL_lose_context')?.loseContext();
    }
  } catch {
    /* reported as unavailable */
  }
  return { webgpu, webgl2, ok: webgpu.startsWith('可用') || webgl2 === '可用', gpu: info };
}

async function fallback(cap: { webgpu: string; webgl2: string }) {
  const m = await import('./ui/fallback');
  await m.showFallback(cap);
  window.__status = { fallback: true, ...cap };
}

async function boot() {
  const params = new URLSearchParams(location.search);
  if (params.has('presenter')) {
    runConsole(params.get('presenter') || 'main');
    return;
  }
  const cap = await capability(params.has('webgl'));
  if (!cap.ok || params.has('fallback')) {
    await fallback(cap);
    return;
  }
  const canvas = document.getElementById('sky') as HTMLCanvasElement;
  // the 3-D application (three.js and all) loads only when it can run
  const { App } = await import('./app/app');
  const app = new App({ canvas, params, gpu: cap.gpu });
  window.__app = app;
  try {
    await app.init();
  } catch (e) {
    // the renderer could not start after all (driver reset, context refused)
    console.error(e);
    document.querySelectorAll('.hud, .labels').forEach((n) => n.remove());
    await fallback({ webgpu: cap.webgpu, webgl2: `${cap.webgl2}，但启动失败：${String(e).slice(0, 80)}` });
    return;
  }
  window.__capture = () => app.engine.captureToOverlay();
  if (params.has('station') && params.has('capture')) {
    // stills: advance time without presenting frames (headless-safe)
    let done = false;
    void app.director?.go(params.get('station')!, { duration: 0.5 }).then(() => (done = true));
    for (let i = 0; i < 600 && !done; i++) {
      app.engine.tick(1 / 30);
      await new Promise((r) => setTimeout(r, 5));
    }
    for (let i = 0; i < 90; i++) app.engine.tick(1 / 30); // let transitions settle
  }
  if (params.has('record')) {
    (await import('./app/record')).installRecorder(app);
  } else if (params.has('capture')) {
    const t0 = performance.now();
    await new Promise((r) => setTimeout(r, 1500));
    while (app.nodes.stats.pending > 0 && performance.now() - t0 < 180000) await new Promise((r) => setTimeout(r, 250));
    await new Promise((r) => setTimeout(r, 1500));
    app.field.u.fadeIn.value = 0.001;
    await app.engine.captureToOverlay();
  } else {
    app.engine.start();
    if (params.has('station')) void app.director?.go(params.get('station')!);
    if (params.has('v')) void app.restore(params.get('v')!);
    if (params.has('display')) attachDisplay(app, params.get('display') || 'main');
    if (params.has('bench')) void import('./app/bench').then((m) => m.runBench(app));
    if (params.has('recordtab')) void import('./app/record').then((m) => m.installTabRecorder(app));
  }
  window.__status = { backend: app.engine.backend, ...app.nodes.stats };
}

boot().catch((e) => {
  console.error(e);
  window.__status = { error: String(e) };
});
