export function icon(name: string): SVGSVGElement {
  const s = svg('svg', { viewBox: '0 0 24 24', width: 22, height: 22, fill: 'none', stroke: 'currentColor', 'stroke-width': 1.5, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true' });
  s.innerHTML = ICONS[name] ?? '';
  return s;
}

export function fmtInt(n: number): string {
  return Math.round(n).toLocaleString('en-US');
}
