/**
 * Stations on the time ruler. Every number shown comes from claims.json
 * (pipeline/claims.py); every quotation is listed in docs/sources.md.
 * Text rules: at most three short lines per card, plain language for
 * high-school students, uncertainty stated where it exists.
 */
import { DEG } from '../astro/constants.gen';
import type { CardContent } from '../ui/hud';

export interface Claim {
  id: string;
  title: string;
  value: number | null;
  unit: string | null;
  display: string;
  method: string;
  inputs: Record<string, number | string>;
  sources: string[];
  series?: Record<string, unknown>[];
  rows?: Record<string, unknown>[];
  [k: string]: unknown;
}

export type Claims = Map<string, Claim>;

export interface StationView {
  scale: 'history' | 'deep';
  /** history: astronomical year; deep: Myr */
  t: number;
  style?: 'obs' | 'atlas';
  /** sky moment overrides (degrees): solar longitude and solar hour angle */
  lam?: number;
  hSun?: number;
  /** dusk: put the Sun this many degrees below the horizon instead of hSun */
  duskAlt?: number;
  look?: { az: number; alt: number; fov: number; dist?: number };
  precession?: boolean;
  motion?: boolean;
  culture?: 'chinese' | 'western' | 'none';
  overlays?: ('poleCircle' | 'meridian' | 'ecliptic' | 'equator')[];
  highlight?: { hips: number[][]; label?: string };
  /** stand on another star (HIP) in deep time */
  observerHip?: number;
  /** take t from a claim's value (e.g. computed closest-approach year) */
  tFromClaim?: string;
  /** deep time: draw the Oort-cloud sketch, a star's track (±Myr around t) */
  oort?: boolean;
  track?: { hip: number; span: number };
  /** deep time: look from the observer towards the Sun */
  lookAtSun?: boolean;
}

export interface StationDef {
  id: string;
  label: string; // short label on the ruler
  /** speaker notes for the presenter console */
  notes?: string;
  view: StationView;
  card: (c: Claims) => CardContent;
}

const fmtYear = (y: number) => (y <= 0 ? `公元前 ${1 - Math.round(y)} 年` : `公元 ${Math.round(y)} 年`);
const pick = (c: Claims, id: string) => c.get(id);

