/**
 * Presenter mode for the final defence:
 *   projector : https://…/?display=ROOM   (only the sky)
 *   laptop    : https://…/?presenter=ROOM (script, timer, next station, controls)
 * Both join the WebSocket room /ws/session/ROOM; the console sends commands,
 * the projector executes them and reports its state back.
 */
import type { App } from './app';
import { STATIONS } from '../content/stations';
import { el } from '../ui/dom';

export type Command =
  | { cmd: 'go'; id: string }
  | { cmd: 'tour'; from?: number }
  | { cmd: 'pause' }
  | { cmd: 'style' }
  | { cmd: 'scale'; scale: 'history' | 'deep' }
  | { cmd: 'state'; station: string | null; year: number; deep: number; style: string; scale: string };

function socket(room: string): WebSocket {
  const proto = location.protocol === 'https:' ? 'wss' : 'ws';
  const base = location.pathname.replace(/[^/]*$/, '');
  return new WebSocket(`${proto}://${location.host}${base}ws/session/${encodeURIComponent(room)}`);
}

/** Projector side: execute commands, report state twice a second. */
export function attachDisplay(app: App, room: string): void {
  let ws = socket(room);
  const connect = () => {
    ws.onmessage = (ev) => {
      const m = JSON.parse(ev.data) as Command;
      if (m.cmd === 'go') void app.director?.go(m.id);
      else if (m.cmd === 'tour') void app.tour?.play(m.from);
      else if (m.cmd === 'pause') app.tour?.pause();
      else if (m.cmd === 'style') app.toggleStyle();
      else if (m.cmd === 'scale') app.setScale(m.scale);
    };
    ws.onclose = () => window.setTimeout(() => {
      ws = socket(room);
      connect();
    }, 1500);
  };
  connect();
  document.body.classList.add('display-mode');
  window.setInterval(() => {
    if (ws.readyState !== WebSocket.OPEN) return;
    const s: Command = { cmd: 'state', station: app.director?.current?.id ?? null, year: app.moment.year, deep: app.deepMyr, style: app.style, scale: app.scale };
    ws.send(JSON.stringify(s));
  }, 500);
}

/** Laptop side: a light console (no 3-D rendering). */
export function runConsole(room: string): void {
  document.body.innerHTML = '';
  document.documentElement.dataset.theme = 'obs';
  const ws = socket(room);
  const send = (c: Command) => ws.readyState === WebSocket.OPEN && ws.send(JSON.stringify(c));
  const t0 = Date.now();
  const clock = el('div', { class: 'pc-clock' }, '00:00');
  const status = el('div', { class: 'pc-status' }, '等待投影窗口连接…');
  const notes = el('div', { class: 'pc-notes' });
  let current = -1;
  const list = el('ol', { class: 'pc-list' }, ...STATIONS.map((s, i) => el('li', {},
    el('button', { onclick: () => { current = i; show(); send({ cmd: 'go', id: s.id }); } }, `${s.label}`))));
  const show = () => {
    list.querySelectorAll('li').forEach((li, i) => li.classList.toggle('now', i === current));
    const s = STATIONS[current];
    notes.replaceChildren(...(s ? [el('h2', {}, s.label), el('p', {}, s.notes ?? ''), el('p', { class: 'pc-next' }, `下一站：${STATIONS[current + 1]?.label ?? '结束'}`)] : []));
  };
  const bar = el('div', { class: 'pc-bar' },
    el('button', { class: 'btn ghost', onclick: () => { current = Math.max(0, current - 1); show(); send({ cmd: 'go', id: STATIONS[current].id }); } }, '上一站'),
    el('button', { class: 'btn primary', onclick: () => { current = Math.min(STATIONS.length - 1, current + 1); show(); send({ cmd: 'go', id: STATIONS[current].id }); } }, '下一站'),
    el('button', { class: 'btn ghost', onclick: () => send({ cmd: 'tour', from: 0 }) }, '播放导览'),
    el('button', { class: 'btn ghost', onclick: () => send({ cmd: 'pause' }) }, '暂停'),
    el('button', { class: 'btn ghost', onclick: () => send({ cmd: 'style' }) }, '今 / 古'),
    el('button', { class: 'btn ghost', onclick: () => send({ cmd: 'scale', scale: 'history' }) }, '地球'),
    el('button', { class: 'btn ghost', onclick: () => send({ cmd: 'scale', scale: 'deep' }) }, '银河'),
  );
  document.body.append(el('div', { class: 'pc' },
    el('header', {}, el('h1', {}, '讲者视图'), el('span', {}, `房间 ${room}`), clock),
    status, bar, el('div', { class: 'pc-cols' }, list, notes)));
  ws.onmessage = (ev) => {
    const m = JSON.parse(ev.data) as Command;
    if (m.cmd === 'state') {
      const y = m.scale === 'deep' ? `${(m.deep * 100).toFixed(1)} 万年` : m.year <= 0 ? `公元前 ${1 - Math.floor(m.year)} 年` : `公元 ${Math.floor(m.year)} 年`;
      status.textContent = `投影：${m.station ?? '自由探索'} · ${y} · ${m.style === 'atlas' ? '古' : '今'}`;
      const i = STATIONS.findIndex((s) => s.id === m.station);
      if (i >= 0 && i !== current) {
        current = i;
        show();
      }
    }
  };
  window.setInterval(() => {
    const s = Math.floor((Date.now() - t0) / 1000);
    clock.textContent = `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
  }, 1000);
}
